<?php
namespace Tests\Feature;
use App\Enums\EditBarrier;use App\Models\PayrollPeriod;use App\Models\PayrollSheet;use App\Models\Project;use App\Models\RoleAssignment;use App\Models\User;use App\Services\Payroll\PayrollAccessService;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class PayrollAccessTest extends TestCase { use RefreshDatabase;
 private function setupSheet(): array {$p1=Project::create(['code'=>'A','name'=>'الف']);$p2=Project::create(['code'=>'B','name'=>'ب']);$period=PayrollPeriod::create(['year'=>1405,'month'=>6,'title'=>'شهریور','edit_deadline_at'=>now()->addDay(),'business_timezone'=>'Asia/Tehran']);$sheet=PayrollSheet::create(['period_id'=>$period->id,'project_id'=>$p1->id,'project_name_snapshot'=>$p1->name]);return[$p1,$p2,$sheet];}
 public function test_operator_only_sees_own_project(): void {[$p1,$p2,$sheet]=$this->setupSheet();$u=User::create(['name'=>'اپراتور','mobile'=>'09121111111']);RoleAssignment::create(['user_id'=>$u->id,'role_code'=>'project_operator','project_id'=>$p2->id,'started_at'=>now()]);$this->assertFalse(app(PayrollAccessService::class)->canView($u->fresh(),$sheet));}
 public function test_operator_is_locked_after_submit_but_manager_can_edit(): void {[$p1,,$sheet]=$this->setupSheet();$sheet->update(['edit_barrier'=>EditBarrier::ProjectOperator]);$op=User::create(['name'=>'اپراتور','mobile'=>'09122222222']);RoleAssignment::create(['user_id'=>$op->id,'role_code'=>'project_operator','project_id'=>$p1->id,'started_at'=>now()]);$manager=User::create(['name'=>'مدیر','mobile'=>'09123333333']);RoleAssignment::create(['user_id'=>$manager->id,'role_code'=>'project_manager','project_id'=>$p1->id,'started_at'=>now()]);$svc=app(PayrollAccessService::class);$this->assertFalse($svc->canEdit($op->fresh(),$sheet->fresh()));$this->assertTrue($svc->canEdit($manager->fresh(),$sheet->fresh()));}
}
